'use client';

import { Plus, Printer, Search, Trash2 } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { KioskPrinter, PrinterRoute, getPrinterRoutes, normalizePrinters } from '@/lib/printer-routing';

const ROUTES: Array<{ id: PrinterRoute; label: string }> = [{ id: 'food', label: 'Cozinha' }, { id: 'beverage', label: 'Bar' }, { id: 'cashier', label: 'Caixa' }];
const RECEIPTS = [
  { title: 'BAR · BEBIDAS', items: ['2x Água de coco', '1x Caipirinha'], notes: 'Uma água sem gelo.' },
  { title: 'COZINHA · ALIMENTOS', items: ['1x Filé com fritas', '1x Porção de camarão'], notes: 'Bem passado; porção sem sal.' },
  { title: 'CAIXA · PEDIDO COMPLETO', items: ['2x Água de coco R$ 20,00', '1x Filé com fritas R$ 58,00'], notes: 'Observações de bar e cozinha.', total: 'R$ 78,00' },
];
type FoundPrinter = { host: string; port: number; name: string; protocol?: string; rawCompatible: boolean; routes: PrinterRoute[]; paperWidth: 58 | 80; columns: number; autoCut: boolean };

export default function PrinterManager({ vendorId }: { vendorId: string }) {
  const [printers, setPrinters] = useState<KioskPrinter[]>([]);
  const [found, setFound] = useState<FoundPrinter[]>([]);
  const [manualName, setManualName] = useState('');
  const [routes, setRoutes] = useState<PrinterRoute[]>(['food']);
  const [additionalPorts, setAdditionalPorts] = useState('');
  const [search, setSearch] = useState('');
  const [message, setMessage] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => { fetch(`/api/printer-settings?vendor_id=${vendorId}`, { cache: 'no-store' }).then(async response => { const data = await response.json(); if (!response.ok) throw new Error(data.error); return data; }).then(data => setPrinters(normalizePrinters(data.printers))).catch(error => setMessage(error instanceof Error ? error.message : 'Erro ao buscar impressoras.')); }, [vendorId]);
  const visible = useMemo(() => printers.filter(item => item.name.toLowerCase().includes(search.toLowerCase())), [printers, search]);
  const persist = async (next: KioskPrinter[]) => { setSaving(true); setMessage(''); try { const response = await fetch('/api/printer-settings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ vendor_id: vendorId, printers: next }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error); setPrinters(normalizePrinters(data.printers)); setMessage('Configuração salva.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Erro ao salvar.'); } finally { setSaving(false); } };
  const discover = async () => { setMessage('Procurando em toda a rede local...'); setFound([]); try { const ports = additionalPorts.split(/[,;\s]+/).map(Number).filter(port => Number.isInteger(port) && port > 0 && port <= 65535).slice(0, 17); const response = await fetch(`http://127.0.0.1:17891/printers?ports=${ports.join(',')}`, { cache: 'no-store' }); const data = await response.json(); if (!response.ok) throw new Error(); const values = (Array.isArray(data.printers) ? data.printers : []).map((item: { host?: string; port?: number; name?: string; protocol?: string; rawCompatible?: boolean }) => ({ host: String(item.host), port: Number(item.port || 9100), name: String(item.name || `Impressora ${item.host}`).slice(0, 80), protocol: item.protocol, rawCompatible: item.rawCompatible !== false, routes: [...routes], paperWidth: 80 as const, columns: 42, autoCut: false })); setFound(values); setMessage(values.length ? `${values.length} serviço(s) encontrado(s). Configure antes de adicionar.` : 'Nenhuma impressora respondeu.'); } catch { setMessage('Execute o Agente de Impressão SandExpress neste desktop.'); } };
  const addFound = (candidate: FoundPrinter) => { if (!candidate.rawCompatible) return setMessage('A impressora foi detectada, mas precisa aceitar impressão RAW na porta configurada.'); if (!candidate.name.trim() || !candidate.routes.length) return setMessage('Informe nome e destino.'); const next: KioskPrinter = { id: `network-${candidate.host}-${candidate.port}`, name: candidate.name.trim(), route: candidate.routes[0], routes: candidate.routes, active: true, connection: 'network', host: candidate.host, port: candidate.port, paperWidth: candidate.paperWidth, columns: candidate.columns, autoCut: candidate.autoCut }; void persist([...printers.filter(item => item.id !== next.id), next]); setFound(current => current.filter(item => item.host !== candidate.host || item.port !== candidate.port)); };
  const addManual = () => { if (!manualName.trim() || !routes.length) return setMessage('Informe nome e destino.'); void persist([...printers, { id: crypto.randomUUID(), name: manualName.trim(), route: routes[0], routes, active: true, paperWidth: 80, columns: 42, autoCut: false }]); setManualName(''); };

  const routeChecks = (selected: PrinterRoute[], change: (next: PrinterRoute[]) => void) => <div className="flex flex-wrap gap-3">{ROUTES.map(target => <label key={target.id} className="flex items-center gap-2 text-sm font-black"><input type="checkbox" checked={selected.includes(target.id)} onChange={event => change(event.target.checked ? [...selected, target.id] : selected.filter(item => item !== target.id))}/>{target.label}</label>)}</div>;
  return <div className="space-y-5">
    <section className="rounded-2xl border border-blue-200 bg-blue-50 p-4 text-blue-950"><p className="font-black">Configuração genérica e segura</p><p className="mt-1 text-sm font-bold">Padrão: papel 80 mm, 42 colunas, quebra automática de linhas e corte desativado para não interromper o pedido. Também aceita 58 mm/32 colunas.</p></section>
    <section className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="flex items-center gap-2 text-xl font-black"><Printer/> Impressoras do quiosque</h2>
      <label className="mt-4 block text-sm font-black">Portas adicionais<input value={additionalPorts} onChange={event => setAdditionalPorts(event.target.value.replace(/[^\d,;\s]/g, ''))} placeholder="Ex.: 9101, 9102, 9200" className="mt-2 min-h-11 w-full rounded-xl border-2 px-3"/><span className="mt-1 block text-xs text-gray-500">9100, 515 e 631 já são verificadas automaticamente.</span></label>
      <div className="mt-4 grid gap-3 lg:grid-cols-[1fr_auto_auto]"><input value={manualName} onChange={event => setManualName(event.target.value)} placeholder="Nome da impressora" className="min-h-12 rounded-xl border-2 px-4 font-bold"/><button disabled={saving} onClick={discover} className="rounded-xl bg-emerald-700 px-5 font-black text-white"><Search className="inline" size={18}/> Buscar rede</button><button disabled={saving} onClick={addManual} className="rounded-xl bg-[#FF6B00] px-5 font-black text-white"><Plus className="inline" size={18}/> Adicionar manual</button></div>
      <div className="mt-3 flex items-center gap-4">{routeChecks(routes, setRoutes)}<button type="button" onClick={() => setRoutes(ROUTES.map(item => item.id))} className="rounded-lg bg-gray-950 px-3 py-2 text-sm font-black text-white">Marcar todas</button></div>
      {found.length ? <div className="mt-5 space-y-3 rounded-2xl bg-emerald-50 p-4">{found.map((candidate, index) => <article key={`${candidate.host}:${candidate.port}`} className="rounded-xl bg-white p-4"><input value={candidate.name} onChange={event => setFound(current => current.map((item, i) => i === index ? { ...item, name: event.target.value } : item))} placeholder="Bar, Cozinha ou Caixa" className="min-h-11 w-full rounded-xl border-2 px-3 font-black"/><p className="mt-1 text-xs font-bold text-gray-500">{candidate.host}:{candidate.port} · {candidate.protocol || 'RAW/ESC-POS'}</p><div className="mt-3">{routeChecks(candidate.routes, next => setFound(current => current.map((item, i) => i === index ? { ...item, routes: next } : item)))}</div><div className="mt-3 grid gap-3 sm:grid-cols-4"><select value={candidate.paperWidth} onChange={event => { const width = Number(event.target.value) as 58 | 80; setFound(current => current.map((item, i) => i === index ? { ...item, paperWidth: width, columns: width === 58 ? 32 : 42 } : item)); }} className="min-h-10 rounded-lg border px-2"><option value="80">Papel 80 mm</option><option value="58">Papel 58 mm</option></select><input type="number" min="24" max="64" value={candidate.columns} onChange={event => setFound(current => current.map((item, i) => i === index ? { ...item, columns: Number(event.target.value) } : item))} aria-label="Colunas" className="min-h-10 rounded-lg border px-2"/><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={candidate.autoCut} onChange={event => setFound(current => current.map((item, i) => i === index ? { ...item, autoCut: event.target.checked } : item))}/>Corte automático</label><button disabled={!candidate.rawCompatible} onClick={() => addFound(candidate)} className="rounded-lg bg-emerald-700 font-black text-white disabled:bg-gray-300">Adicionar</button></div></article>)}</div> : null}
      <div className="relative mt-5"><Search className="absolute left-3 top-3.5 text-gray-400" size={18}/><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar cadastrada" className="min-h-12 w-full rounded-xl border-2 pl-10 pr-4 font-bold"/></div>
      <div className="mt-4 space-y-2">{visible.map(printer => <article key={printer.id} className="rounded-xl border p-4"><div className="flex justify-between"><div><p className="font-black">{printer.name}</p><p className="text-xs font-bold text-emerald-700">{printer.host ? `${printer.host}:${printer.port || 9100}` : 'Navegador'} · {printer.paperWidth || 80} mm · {printer.columns || 42} colunas · corte {printer.autoCut ? 'ativo' : 'desativado'}</p></div><button onClick={() => void persist(printers.filter(item => item.id !== printer.id))} className="rounded-lg bg-red-50 p-2 text-red-600"><Trash2 size={18}/></button></div><div className="mt-3">{routeChecks(getPrinterRoutes(printer), next => { if (next.length) void persist(printers.map(item => item.id === printer.id ? { ...item, route: next[0], routes: next } : item)); })}</div></article>)}{!visible.length ? <p className="rounded-xl bg-gray-50 p-4 font-bold text-gray-500">Nenhuma impressora cadastrada.</p> : null}</div>{message ? <p className="mt-4 rounded-xl bg-orange-50 p-3 font-black text-[#8A3E22]">{message}</p> : null}
    </section>
    <section className="rounded-2xl border bg-white p-5 shadow-sm"><h2 className="text-xl font-black">Modelo de impressão</h2><div className="mt-4 grid gap-4 xl:grid-cols-3">{RECEIPTS.map(receipt => <article key={receipt.title} className="mx-auto w-full max-w-[300px] border border-dashed p-4 font-mono text-sm"><h3 className="border-b border-dashed pb-2 text-center font-black">{receipt.title}</h3><p className="mt-2">Guarda-sol: 18<br/>Pedido: 1042</p><hr className="my-2 border-dashed"/>{receipt.items.map(item => <p key={item}>{item}</p>)}<hr className="my-2 border-dashed"/><p><b>OBSERVAÇÕES:</b><br/>{receipt.notes}</p>{receipt.total ? <p className="mt-3 font-black">TOTAL: {receipt.total}</p> : null}</article>)}</div></section>
  </div>;
}

